-- A person's holds are dated: each applies from its from-date to its to-date (open-ended when it
-- has none), and a person may have several over time. While a hold covers a claim's date, the
-- person's open claim of that date (one not bound by a statement) counts in no live total. A person
-- on hold before holds were dated keeps a hold from the beginning of time (no from-date).
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A person's aliases: each stored with surrounding spaces removed. An alias shares the names'
-- uniqueness on the sheet (compared without regard to case), which the service keeps.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias)
);
-- The sheet's history: after each change that can move its figures, a revision of every claim,
-- person, rate and dated setting the change left different from its last revision (and of the
-- policy date), stamped with the sheet's today then. The sheet as it stood at the end of a day is
-- the last revision of each stamped on or before that day.
CREATE TABLE claim_revision (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id       BIGINT         NOT NULL,
    recorded_on    DATE           NOT NULL,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(14, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(20)    NOT NULL,
    settled_due    DECIMAL(14, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(14, 2),
    stated_na      BOOLEAN        NOT NULL,
    corrected_date DATE,
    due_by         DATE           NOT NULL,
    deferred_until DATE
);
CREATE INDEX claim_revision_sheet ON claim_revision (sheet_id, id);

-- A person's grades and holds are kept as text: each grade "from:grade" and each hold "from..to"
-- (a day left blank when there is none), separated by ";".
CREATE TABLE person_revision (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    person_id    BIGINT        NOT NULL,
    recorded_on  DATE          NOT NULL,
    name         VARCHAR(200)  NOT NULL,
    grades       VARCHAR(4000) NOT NULL,
    holds        VARCHAR(4000) NOT NULL,
    retired_from DATE,
    terms        INT
);
CREATE INDEX person_revision_sheet ON person_revision (sheet_id, id);

CREATE TABLE rate_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade       VARCHAR(1)   NOT NULL,
    from_date   DATE,
    recorded_on DATE         NOT NULL,
    pct         DECIMAL(7, 2) NOT NULL,
    to_date     DATE
);
CREATE INDEX rate_revision_sheet ON rate_revision (sheet_id, id);

CREATE TABLE setting_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(50)    NOT NULL,
    from_date   DATE           NOT NULL,
    recorded_on DATE           NOT NULL,
    setting     DECIMAL(14, 2)
);
CREATE INDEX setting_revision_sheet ON setting_revision (sheet_id, id);

CREATE TABLE sheet_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    recorded_on DATE         NOT NULL,
    policy_date DATE
);
CREATE INDEX sheet_revision_sheet ON sheet_revision (sheet_id, id);

-- What a sheet holds already is its first revision, stamped with its today.
INSERT INTO claim_revision (sheet_id, claim_id, recorded_on, person_id, amount, claim_date, status, settled_due,
        stated, stated_due, stated_na, corrected_date, due_by, deferred_until)
    SELECT c.sheet_id, c.id, s.today, c.person_id, c.amount, c.claim_date, c.status, c.settled_due, c.stated,
        c.stated_due, c.stated_na, c.corrected_date, c.due_by, c.deferred_until
    FROM claim c JOIN sheet s ON s.id = c.sheet_id ORDER BY c.id;
INSERT INTO person_revision (sheet_id, person_id, recorded_on, name, grades, holds, retired_from, terms)
    SELECT p.sheet_id, p.id, s.today, p.name,
        COALESCE((SELECT LISTAGG(COALESCE(CAST(g.from_date AS VARCHAR), '') || ':' || g.grade, ';')
            WITHIN GROUP (ORDER BY g.from_date NULLS FIRST) FROM person_grade g WHERE g.person_id = p.id), ''),
        COALESCE((SELECT LISTAGG(COALESCE(CAST(h.from_date AS VARCHAR), '') || '..'
            || COALESCE(CAST(h.to_date AS VARCHAR), ''), ';')
            WITHIN GROUP (ORDER BY h.from_date NULLS FIRST) FROM person_hold h WHERE h.person_id = p.id), ''),
        p.retired_from, p.terms
    FROM person p JOIN sheet s ON s.id = p.sheet_id ORDER BY p.id;
INSERT INTO rate_revision (sheet_id, grade, from_date, recorded_on, pct, to_date)
    SELECT r.sheet_id, r.grade, r.from_date, s.today, r.pct, r.to_date
    FROM rate r JOIN sheet s ON s.id = r.sheet_id ORDER BY r.id;
INSERT INTO setting_revision (sheet_id, setting_key, from_date, recorded_on, setting)
    SELECT v.sheet_id, v.setting_key, v.from_date, s.today, v.setting
    FROM setting_value v JOIN sheet s ON s.id = v.sheet_id;
INSERT INTO sheet_revision (sheet_id, recorded_on, policy_date)
    SELECT id, today, policy_date FROM sheet WHERE policy_date IS NOT NULL;

-- A statement may be taken as of an earlier day than the sheet's today: that day, null when it was
-- taken as of the sheet's today.
ALTER TABLE statement ADD COLUMN as_of DATE;
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** A person on a sheet: a name and a grade (A, B or C), dated: each grade applies from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The person's place in the sheet's list, smallest first; a new person goes to the end. */
    @Column(name = "position", nullable = false)
    private long position;

    /** The grades the person was given, each from its from-date; the first has none. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The day the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's holds: their open claims dated within one count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The person's own terms in days; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's aliases, each trimmed; unique on the sheet among names and aliases as names are
     *  compared. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias")
    private Set<String> aliases = new HashSet<>();

    /** The sheet the person was transferred from; null when they were not transferred. */
    @Column(name = "origin")
    private String origin;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    /** A detached person with the id given and no grade yet, for a revision to fill in (see
     *  {@link PersonRevision#toPerson}). */
    Person(String sheetId, Long id, String name) {
        this.sheetId = sheetId;
        this.id = id;
        this.name = name;
    }

    public Person(String sheetId, String name, String grade, long position) {
        this.sheetId = sheetId;
        this.name = name;
        this.position = position;
        this.grades.add(new GradeFrom(null, grade));
    }

    /** A copy of the person for another sheet (they were transferred there): their name, every
     *  grade they were given (and its from-date), terms, contact and aliases; no holds. They take
     *  the place given in that sheet's list. */
    public Person transferredTo(String toSheetId, long toPosition) {
        Person copy = new Person(toSheetId, (Long) null, name);
        copy.position = toPosition;
        grades.forEach(g -> copy.grades.add(new GradeFrom(g.getFromDate(), g.getGrade())));
        copy.terms = terms;
        copy.contact = contact;
        copy.aliases.addAll(aliases);
        copy.origin = sheetId;
        return copy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public long getPosition() {
        return position;
    }

    /** The grades the person was given, earliest from-date first, the one with none first of all. */
    public List<GradeFrom> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on a day: the one with the latest from-date on or before it, or else the
     *  one with no from-date. */
    public String gradeOn(LocalDate day) {
        String on = null;
        for (GradeFrom g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(day)) {
                on = g.getGrade();
            }
        }
        return on;
    }

    /** Record a grade from a day (null: the beginning of time), replacing the one recorded for that
     *  day, keeping the others. */
    public void setGradeFrom(String grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(from, g.getFromDate()));
        grades.add(new GradeFrom(from, grade));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether the person is retired: they are as soon as a retirement day is set, whatever the day. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person is retired on a day: their retirement day is set and the day is on or after it.
     *  From then their open claims unbound by a statement count in no live total. */
    public boolean isRetiredOn(LocalDate day) {
        return retiredFrom != null && !day.isBefore(retiredFrom);
    }

    /** The person's holds, earliest from-date first, those with none first of all. */
    public List<Hold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(Hold::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Whether the person has any hold, whatever its days. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether one of the person's holds covers a day. */
    public boolean isHeldOn(LocalDate day) {
        return holds.stream().anyMatch(h -> h.covers(day));
    }

    /** Add a hold, keeping the others. */
    public void addHold(LocalDate from, LocalDate to) {
        holds.add(new Hold(from, to));
    }

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The sheet the person was transferred from; null when they were not transferred. */
    public String getOrigin() {
        return origin;
    }

    /** The person's contact, held by no one else on the sheet; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(Comparator.naturalOrder()))
                .toList();
    }

    /** Add an alias, keeping the others. */
    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person, from its from-date (from the beginning of time when it has none) to its
 *  to-date (open-ended when it has none), both days included. */
@Embeddable
public class Hold {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {
    }

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the hold covers a day. */
    public boolean covers(LocalDate day) {
        return (fromDate == null || !day.isBefore(fromDate)) && (toDate == null || !day.isAfter(toDate));
    }
}

