        this.name = name;
    }

    public long getPosition() {
        return position;
    }

    /** The grades the person was given, earliest from-date first, the one with none first of all. */
    public List<GradeFrom> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on a day: the one with the latest from-date on or before it, or else the
     *  one with no from-date. */
    public String gradeOn(LocalDate day) {
        String on = null;
        for (GradeFrom g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(day)) {
                on = g.getGrade();
            }
        }
        return on;
    }

    /** Record a grade from a day (null: the beginning of time), replacing the one recorded for that
     *  day, keeping the others. */
    public void setGradeFrom(String grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(from, g.getFromDate()));
        grades.add(new GradeFrom(from, grade));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether the person is retired: they are as soon as a retirement day is set, whatever the day. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person is retired on a day: their retirement day is set and the day is on or after it.
     *  From then their open claims unbound by a statement count in no live total. */
    public boolean isRetiredOn(LocalDate day) {
        return retiredFrom != null && !day.isBefore(retiredFrom);
    }

    /** The person's holds, earliest from-date first, those with none first of all. */
    public List<Hold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(Hold::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Whether the person has any hold, whatever its days. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether one of the person's holds covers a day. */
    public boolean isHeldOn(LocalDate day) {
        return holds.stream().anyMatch(h -> h.covers(day));
    }

    /** Add a hold, keeping the others. */
    public void addHold(LocalDate from, LocalDate to) {
        holds.add(new Hold(from, to));
    }

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The sheet the person was transferred from; null when they were not transferred. */
    public String getOrigin() {
        return origin;
    }

    /** The person's contact, held by no one else on the sheet; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(Comparator.naturalOrder()))
                .toList();
    }

    /** Add an alias, keeping the others. */
    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person, from its from-date (from the beginning of time when it has none) to its
 *  to-date (open-ended when it has none), both days included. */
@Embeddable
public class Hold {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {
    }

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the hold covers a day. */
    public boolean covers(LocalDate day) {
        return (fromDate == null || !day.isBefore(fromDate)) && (toDate == null || !day.isAfter(toDate));
    }
}

package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;
import java.util.function.Predicate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;
    private final RoleService roles;

    public PersonService(PersonRepository people, SheetService sheets, Rollup rollup, Audit audit,
            RoleService roles) {
        this.people = people;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
        this.roles = roles;
    }

    /** The people on the sheet in list order. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
    }

    /** Add a person to the sheet. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    /** Add a person to the sheet with a contact (null: none); refused when another person on the
     *  sheet holds it. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        sheets.load(sheetId, user);
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name) || people.existsAlias(sheetId, name)
                || inTree(treeNames(sheetId), name)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
            throw contactInUse();
        }
        return rollup.tracking(sheetId, user, () -> {
            Person fresh = new Person(sheetId, name, grade, people.nextPosition(sheetId));
            fresh.setTerms(terms);
            fresh.setContact(contact);
            Person person = saveUnique(fresh);
            audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId))
                    + (terms != null ? " terms=" + terms : "")
                    + (contact != null ? " contact=" + contact : ""));
            return person;
        });
    }

    /** Change a person's name, and record their grade from a day (null: the sheet's today), keeping
     *  the grades already recorded; a grade left as the one in force on the sheet's today, with no
     *  day given, records nothing; and set their own terms (null: none) and contact (null: none),
     *  refused when another person on the sheet holds that contact. Also refused when the person is no longer at the version the editor
     *  loaded: another user saved them in the meantime. */
    @Transactional
    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, personId)
                || people.existsAlias(sheetId, name)) {
            throw nameInUse();
        }
        Set<String> tree = treeNames(sheetId);
        if (inTree(tree, name) || person.getAliases().stream().anyMatch(a -> inTree(tree, a))) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, personId)) {
            throw contactInUse();
        }
        return save(sheetId, user, person, name, grade, gradeFrom, terms, contact);
    }

    /** Give each of the people a grade from a day (null: the sheet's today), in list order, exactly as the person form would: each keeps their name, terms and contact and
     *  is followed by their own PERSON_EDITED and rollup lines. Refused as a whole, changing no one,
     *  when an id names no person on the sheet. A viewer has each of them refused: no one changes. */
    @Transactional
    public List<Person> grade(String sheetId, String user, Set<Long> personIds, String grade, LocalDate gradeFrom) {
        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
            return List.of();
        }
        List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .filter(p -> personIds.contains(p.getId())).toList();
        if (chosen.size() != personIds.size()) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
        }
        return chosen.stream()
                .map(p -> save(sheetId, user, p, p.getName(), grade, gradeFrom, p.getTerms(), p.getContact()))
                .toList();
    }

    /** Save the person's name, grade from a day, terms and contact as an edit does, recording it. */
    private Person save(String sheetId, String user, Person person, String name, String grade, LocalDate gradeFrom,
            Integer terms, String contact) {
        return rollup.tracking(sheetId, user, () -> {
            LocalDate today = sheets.today(sheetId);
            Integer termsBefore = person.getTerms();
            String contactBefore = person.getContact();
            person.setName(name);
            person.setTerms(terms);
            person.setContact(contact);
            if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
                person.setGradeFrom(grade, gradeFrom != null ? gradeFrom : today);
            }
            Person saved = saveUnique(person);
            audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
                    + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
                    + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
            return saved;
        });
    }

    /** Give a person an alias, keeping their others; refused when it equals, as names are compared,
     *  any name or alias on the sheet. */
    @Transactional
    public Person addAlias(String sheetId, String user, long personId, String alias) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, alias) || people.existsAlias(sheetId, alias)
                || inTree(treeNames(sheetId), alias)) {
            throw nameInUse();
        }
        person.addAlias(alias);
        Person saved = saveUnique(person);
        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " alias=" + alias);
        return saved;
    }

    /** Whether the person clashes: their name or an alias is used as a name or alias on another
     *  sheet of their sheet's tree (see {@link SheetService#tree}). */
    @Transactional(readOnly = true)
    public boolean clashing(String sheetId, Person person) {
        return clashing(sheetId).test(person);
    }

    /** A test of whether a person on the sheet clashes, reading the sheet's tree once. */
    @Transactional(readOnly = true)
    public Predicate<Person> clashing(String sheetId) {
        Set<String> tree = treeNames(sheetId);
        if (tree.isEmpty()) {
            return p -> false;
        }
        return p -> inTree(tree, p.getName()) || p.getAliases().stream().anyMatch(a -> inTree(tree, a));
    }

    /** The names and aliases used on the other sheets of the sheet's tree, lower-cased. */
    private Set<String> treeNames(String sheetId) {
        Set<String> tree = sheets.tree(sheetId);
        if (tree.isEmpty()) {
            return Set.of();
        }
        Set<String> names = new HashSet<>(people.namesOn(tree));
        names.addAll(people.aliasesOn(tree));
        return names;
    }

    private static boolean inTree(Set<String> treeNames, String name) {
        return treeNames.contains(name.toLowerCase(Locale.ROOT));
    }

    /** Swap a person with the one above them in the list (up) or below them (down), recording their
     *  new position counting from 1; refused when they are at the top and moving up, or at the
     *  bottom and moving down. Answers the people in their new list order. */
    @Transactional
    public List<Person> move(String sheetId, String user, long personId, boolean up) {
        List<Person> listed = new ArrayList<>(people.findBySheetIdOrderByPositionAscIdAsc(sheetId));
        int at = -1;
        for (int i = 0; i < listed.size(); i++) {
            if (listed.get(i).getId() == personId) {
                at = i;
            }
        }
        if (at < 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
        }
        int to = up ? at - 1 : at + 1;
        if (to < 0 || to >= listed.size()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    up ? "The person at the top cannot move up" : "The person at the bottom cannot move down");
        }
        Person moved = listed.get(at);
        Collections.swap(listed, at, to);
        // Number the whole list afresh from 1, so people who shared a position are told apart.
        for (int i = 0; i < listed.size(); i++) {
            if (listed.get(i).getPosition() != i + 1) {
                people.placeAt(listed.get(i).getId(), i + 1);
            }
        }
        audit.recordOnCommit("PERSON_MOVED sheet=" + sheetId + " by=" + user + " name=" + moved.getName()
                + " position=" + (to + 1));
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
    }

    /** Retire each of the people from a day (null: the sheet's today), in list order, exactly as a
     *  row's retire would: each is followed by their own PERSON_RETIRED and rollup lines. Refused as
     *  a whole, changing no one, when an id names no person on the sheet. A viewer has each of them
     *  refused: no one changes. */
    @Transactional
    public List<Person> retire(String sheetId, String user, Set<Long> personIds, LocalDate from) {
        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
            return List.of();
        }
        List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .filter(p -> personIds.contains(p.getId())).toList();
        if (chosen.size() != personIds.size()) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
        }
        return chosen.stream().map(p -> retire(sheetId, user, p, from)).toList();
    }

    /** Retire a person from a day; a day left out takes the sheet's today. */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        return retire(sheetId, user, person, from);
    }

    /** Retire the person from a day (null: the sheet's today), recording it. */
    private Person retire(String sheetId, String user, Person person, LocalDate from) {
        LocalDate on = from != null ? from : sheets.today(sheetId);
        return rollup.tracking(sheetId, user, () -> {
            person.setRetiredFrom(on);
            Person saved = saveUnique(person);
            audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                    + " from=" + on);
            return saved;
        });
    }

    /** Put a person on hold from a day (null: the sheet's today) to a day (null: open-ended),
     *  keeping their other holds; refused when the to-date is before the from-date. */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
        }
        return rollup.tracking(sheetId, user, () -> {
            person.addHold(on, to);
            Person saved = saveUnique(person);
            audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                    + " from=" + on);
            return saved;
        });
    }

    /** A record of the person with the grade in force on the sheet's today. */
    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
                + person.gradeOn(today);
    }

    /** Save, refusing a name or contact another user took on the sheet in the meantime, or a person
     *  another user saved in the meantime. */
    private Person saveUnique(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            String constraint = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
            throw constraint.contains("PERSON_SHEET_CONTACT_UNIQUE") ? contactInUse() : nameInUse();
        } catch (OptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else saved this person in the meantime");
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already held on this sheet");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.role.ViewerAllowed;
import net.officefloor.hq.app.sheet.AsOfGuard;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementSummary;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** What the screen shows of a person; with how many statements were taken of them, and the
     *  last one's due-total (text with two decimals, null when n/a or none) and day (null when none);
     *  whether they are retired, and from which day (null when not); and whether they have any hold, and their holds, earliest first; and their own terms in days (null: none); and their contact (null: none); and their aliases, sorted as names are compared; and whether they clash; and the sheet they were transferred from (null: none) (see
     *  {@link PersonService#clashing}).
     *  The grade is the one in force on the sheet's today; grades are all those recorded, each from
     *  its from-date (null: the beginning of time), earliest first. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            boolean held, List<HoldView> holds, Integer terms, String contact, List<String> aliases, boolean clashing, String origin) {
        public static PersonView of(Person person, StatementSummary statements, LocalDate today,
                boolean clashing) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList(),
                    person.getVersion(), statements.count(),
                    statements.lastDueTotal() == null ? null : statements.lastDueTotal().setScale(2).toPlainString(),
                    statements.lastTakenOn(), person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    person.getTerms(), person.getContact(), person.getAliases(), clashing, person.getOrigin());
        }
    }

    /** A grade recorded for a person, from a day (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /** A hold on a person, from a day (null: from the beginning of time) to a day (null: open-ended). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** The person form: a required name and a grade of A, B or C. An edit also gives the version
     *  of the person its editor loaded, and the day the grade applies from (left out, the sheet's
     *  today). Terms are the person's own, a whole number of days, 0 or more; blank for none. The
     *  contact is kept trimmed and lower-cased; blank for none. */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, Long version, LocalDate gradeFrom,
            @Pattern(regexp = "\\s*\\d{0,4}\\s*") String terms, @Size(max = 200) String contact) {
        Integer termsValue() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }

        String contactValue() {
            return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
        }
    }

    /** The alias form: a required alias, kept trimmed. */
    public record AliasForm(@NotBlank @Size(max = 200) String alias) {
    }

    /** The merge form: the person the merged person is merged into. */
    public record MergeForm(@NotNull Long intoId) {
    }

    /** The transfer form: the id of the sheet the person is transferred to. */
    public record TransferForm(@NotBlank @Size(max = 100) String toSheet) {
    }

    /** The retire form: the day the person is retired from; left out, the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** The hold form: the day the hold starts (left out, the sheet's today) and the day it ends
     *  (left out, it is open-ended). */
    public record HoldForm(LocalDate from, LocalDate to) {
    }

    /** The move form: up or down the list. */
    public record MoveForm(@NotNull @Pattern(regexp = "up|down") String direction) {
    }

    /** The bulk grade form: the people to give the grade, a grade of A, B or C, and the day it
     *  applies from (left out, the sheet's today). */
    public record GradeForm(@NotNull @Size(max = 1000) Set<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate from) {
    }

    /** How many people a bulk grade changed, and those people as they now show. */
    public record Graded(int graded, List<PersonView> people) {
    }

    /** The bulk retire form: the people to retire and the day they are retired from (left out, the
     *  sheet's today). */
    public record BulkRetireForm(@NotNull @Size(max = 1000) Set<@NotNull Long> personIds, LocalDate from) {
    }

    /** How many people a bulk retire retired, and those people as they now show. */
    public record Retired(int retired, List<PersonView> people) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;
    private final History history;
    private final PersonMergeService merges;
    private final PersonTransferService transfers;

    public PersonController(PersonService service, StatementService statements, SheetService sheets,
            History history, PersonMergeService merges, PersonTransferService transfers) {
        this.history = history;
        this.merges = merges;
        this.transfers = transfers;
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    /** The people on the sheet; as of a day when one is given, as they stood at the end of it (see
     *  {@link History}), that day standing in for the sheet's today. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        String sheet = sheetId.trim();
        if (asOf != null) {
            Map<Long, StatementSummary> then = statements.summaries(sheet, asOf);
            Predicate<Person> clashingThen = service.clashing(sheet);
            Map<Long, Integer> place = new HashMap<>();
            List<Person> listed = service.list(sheet);
            for (int i = 0; i < listed.size(); i++) {
                place.put(listed.get(i).getId(), i);
            }
            return history.asOf(sheet, asOf).people().values().stream()
